class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val repository = FinanceRepository(this)
        setContent { val vm: FinanceViewModel = viewModel(factory = FinanceViewModel.Factory(repository, applicationContext)); LumaApp(vm, intent?.getStringExtra("destination") == "quick", contentResolver) }
    }
}

class FinanceViewModel(private val repo: FinanceRepository, private val context: android.content.Context) : ViewModel() {
    val accounts=repo.accounts; val entries=repo.entries; val goals=repo.goals; val projects=repo.projects
    private val preferences=context.getSharedPreferences("luma-preferences",android.content.Context.MODE_PRIVATE)
    var dark by mutableStateOf(preferences.getBoolean("dark",false))
        private set
    var spanish by mutableStateOf(preferences.getString("language",null)?.let{it=="es"} ?: (Locale.getDefault().language=="es"))
        private set
    var message by mutableStateOf("")
    init { viewModelScope.launch { repo.seed() } }
    fun saveEntry(id:String?, amount:String, type:String, category:String, note:String, date:String, account:String, target:String?, project:String?) = viewModelScope.launch {
        try { val cents=parseCents(amount); val day=LocalDate.parse(date).toEpochDay(); repo.saveEntry(id,cents,type,category,note,day,account,target,project); message=tr(spanish,"Movimiento guardado","Transaction saved"); refreshAllWidgets(context) }
        catch(_:Exception){message=tr(spanish,"Revisa el monto, la fecha y la cuenta","Check amount, date and account")}
    }
    fun deleteEntry(id:String)=viewModelScope.launch{repo.deleteEntry(id);refreshAllWidgets(context)}
    fun saveAccount(name:String,type:String,amount:String,currency:String)=viewModelScope.launch{runCatching{repo.saveAccount(name,type,if(amount.isBlank())0 else parseCents(amount),currency.trim().uppercase())}.onFailure{message=it.message?:"Error"};refreshAllWidgets(context)}
    fun saveGoal(name:String,amount:String)=viewModelScope.launch{runCatching{repo.saveGoal(name,parseCents(amount))}.onFailure{message=it.message?:"Error"};refreshAllWidgets(context)}
    fun contributeToGoal(id:String,amount:String)=viewModelScope.launch{runCatching{repo.addGoalSavings(id,parseCents(amount))}.onFailure{message=it.message?:"Error"};refreshAllWidgets(context)}
    fun saveProject(name:String,amount:String,currency:String)=viewModelScope.launch{runCatching{repo.saveProject(name,parseCents(amount),currency.trim().uppercase())}.onFailure{message=it.message?:"Error"}}
    suspend fun backup()=repo.backup(); suspend fun csv()=repo.csv(); suspend fun restore(source:String){repo.restore(source);message=tr(spanish,"Copia restaurada","Backup restored");refreshAllWidgets(context)}
    fun toggleDark(){dark=!dark;preferences.edit().putBoolean("dark",dark).apply()}
    fun toggleLanguage(){spanish=!spanish;preferences.edit().putString("language",if(spanish)"es" else "en").apply()}
    class Factory(private val repo:FinanceRepository,private val context:android.content.Context):ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST") override fun <T:ViewModel> create(modelClass:Class<T>):T = FinanceViewModel(repo,context) as T
    }
    companion object { fun parseCents(value:String):Long { val v=value.trim().replace(",",".").toBigDecimal();require(v>java.math.BigDecimal.ZERO);return v.movePointRight(2).setScale(0,java.math.RoundingMode.HALF_UP).longValueExact() } }
}

private val purple=Color(0xFF7064E8); private val mint=Color(0xFF32B994); private val rose=Color(0xFFE87988); private val muted=Color(0xFF777286)
private fun tr(es:Boolean,english:String,spanish:String)=if(es)spanish else english
private fun cash(cents:Long,currency:String="USD")=currency+" "+String.format(Locale.US,"%,.2f",cents/100.0)
private fun cashByCurrency(values:Map<String,Long>)=if(values.isEmpty())"USD 0.00" else values.entries.joinToString("   ·   "){(currency,cents)->cash(cents,currency)}

@Composable private fun LumaApp(vm:FinanceViewModel,quick:Boolean,resolver:android.content.ContentResolver){
    val accounts by vm.accounts.collectAsState(emptyList());val entries by vm.entries.collectAsState(emptyList());val goals by vm.goals.collectAsState(emptyList());val projects by vm.projects.collectAsState(emptyList())
    val es=vm.spanish;var tab by remember{mutableIntStateOf(if(quick)1 else 0)};var dialog by remember{mutableStateOf(if(quick)"transaction" else "")};var editing by remember{mutableStateOf<LedgerEntry?>(null)};var selectedGoal by remember{mutableStateOf<Goal?>(null)};var editType by remember{mutableStateOf("expense")};var month by remember{mutableStateOf(YearMonth.now())};var pending by remember{mutableStateOf("")};val scope= rememberCoroutineScope();val snack= remember{SnackbarHostState()}
    val jsonSave=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/json")){uri->if(uri!=null)scope.launch{runCatching{resolver.openOutputStream(uri)?.bufferedWriter()?.use{it.write(pending)}}.onFailure{vm.message=it.message?:"Export failed"}}}
    val csvSave=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("text/csv")){uri->if(uri!=null)scope.launch{runCatching{resolver.openOutputStream(uri)?.bufferedWriter()?.use{it.write(pending)}}.onFailure{vm.message=it.message?:"Export failed"}}}
    val restore=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null)scope.launch{runCatching{resolver.openInputStream(uri)?.bufferedReader()?.use{vm.restore(it.readText())}}.onFailure{vm.message=it.message?:"Restore failed"}}}
    LaunchedEffect(vm.message){if(vm.message.isNotBlank())snack.showSnackbar(vm.message)}
    val background=if(vm.dark)Color(0xFF12111A) else Color(0xFFF5F4FA);val surface=if(vm.dark)Color(0xFF22202D) else Color.White;val ink=if(vm.dark)Color.White else Color(0xFF251F36)
    MaterialTheme(colorScheme=if(vm.dark)darkColorScheme(primary=Color(0xFFB0A7FF),background=background,surface=surface,onSurface=ink) else lightColorScheme(primary=purple,background=background,surface=surface,onSurface=ink)){
        Scaffold(containerColor=background,snackbarHost={SnackbarHost(snack)},floatingActionButton={if(tab<4)FloatingActionButton(onClick={editing=null;editType="expense";dialog="transaction"},containerColor=purple,contentColor=Color.White){Icon(Icons.Default.Add,null)}},bottomBar={NavBar(tab,es,surface){tab=it}}){pad->
            Box(Modifier.fillMaxSize().padding(pad)){
                when(tab){
                    0->Home(accounts,entries,goals,month,{month=it},es,ink,surface,{tab=1},{tab=2},{selectedGoal=it;dialog="contribution"})
                    1->Activity(entries,accounts,es,ink,surface,{editing=it;editType=it.type;dialog="transaction"},vm::deleteEntry)
                    2->Reports(entries,accounts,es,ink,surface)
                    3->Plans(goals,projects,entries,accounts,es,ink,surface,{dialog="goal"},{dialog="project"},{selectedGoal=it;dialog="contribution"})
                    else->Settings(accounts,entries,es,ink,surface,{dialog="account"},{vm.toggleDark()},{vm.toggleLanguage()},{scope.launch{runCatching{pending=vm.csv();csvSave.launch("luma-transactions.csv")}.onFailure{vm.message=it.message?:"Export failed"}}},{scope.launch{runCatching{pending=vm.backup();jsonSave.launch("luma-backup.json")}.onFailure{vm.message=it.message?:"Backup failed"}}},{restore.launch(arrayOf("application/json","text/*"))},{dialog="project"})
                }
                if(dialog=="transaction")TransactionForm(editing,editType,accounts,projects,es,{dialog=""},{id,a,t,c,n,d,ac,target,project->vm.saveEntry(id,a,t,c,n,d,ac,target,project);dialog=""})
                if(dialog in listOf("account","goal","project"))EntityForm(dialog,es,{dialog=""},{n,a,x,y->when(dialog){"account"->vm.saveAccount(n,x,a,y);"goal"->vm.saveGoal(n,a);else->vm.saveProject(n,a,x)};dialog=""})
                if(dialog=="contribution" && selectedGoal!=null) ContributionForm(selectedGoal!!,es,{dialog=""},{amount->vm.contributeToGoal(selectedGoal!!.id,amount);dialog=""})
            }
        }
    }
}

@Composable private fun NavBar(tab:Int,es:Boolean,surface:Color,go:(Int)->Unit){val items=listOf(Icons.Default.Home to tr(es,"Home","Inicio"),Icons.Default.ReceiptLong to tr(es,"Activity","Actividad"),Icons.Default.InsertChart to tr(es,"Reports","Análisis"),Icons.Default.Flag to tr(es,"Goals","Metas"),Icons.Default.MoreHoriz to tr(es,"More","Más"));Surface(Modifier.fillMaxWidth().padding(horizontal=14.dp,vertical=7.dp).height(66.dp),shape=RoundedCornerShape(26.dp),color=surface.copy(alpha=.96f),shadowElevation=10.dp){Row(Modifier.fillMaxSize(),horizontalArrangement=Arrangement.SpaceEvenly,verticalAlignment=Alignment.CenterVertically){items.forEachIndexed{i,it->val width by animateDpAsState(if(i==tab)86.dp else 48.dp,label="nav");Row(Modifier.width(width).height(45.dp).clip(CircleShape).background(if(tab==i)purple.copy(alpha=.12f) else Color.Transparent).clickable{go(i)},verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.Center){Icon(it.first,null,tint=if(tab==i)purple else muted,modifier=Modifier.size(21.dp));if(tab==i)Text(it.second,Modifier.padding(start=5.dp),color=purple,fontSize=11.sp,fontWeight=FontWeight.SemiBold)}}}}}

