@Composable private fun Activity(entries:List<LedgerEntry>,accounts:List<Account>,es:Boolean,ink:Color,surface:Color,edit:(LedgerEntry)->Unit,delete:(String)->Unit){var query by remember{mutableStateOf("")};var filter by remember{mutableStateOf("all")};Column(Modifier.fillMaxSize().padding(horizontal=19.dp)){Text(tr(es,"Activity","Actividad"),Modifier.padding(top=16.dp),fontSize=27.sp,color=ink,fontWeight=FontWeight.Bold);OutlinedTextField(query,{query=it},Modifier.fillMaxWidth().padding(top=9.dp),placeholder={Text(tr(es,"Search transactions","Buscar movimientos"))},leadingIcon={Icon(Icons.Default.Search,null)},shape=RoundedCornerShape(17.dp),singleLine=true);Row(Modifier.horizontalScroll(rememberScrollState()).padding(vertical=9.dp),horizontalArrangement=Arrangement.spacedBy(6.dp)){listOf("all","income","expense","transfer").forEach{FilterChip(filter==it,{filter=it},label={Text(when(it){"all"->tr(es,"All","Todos");"income"->tr(es,"Income","Ingresos");"expense"->tr(es,"Expenses","Gastos");else->tr(es,"Transfers","Transferencias")})})}};val filtered=entries.filter{(filter=="all"||it.type==filter)&&(it.category+it.note).contains(query,true)};LazyColumn(contentPadding=PaddingValues(bottom=100.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){if(filtered.isEmpty())item{Empty(tr(es,"Nothing here yet","Todavía no hay movimientos"),tr(es,"Transactions you add will appear here.","Aquí aparecerán tus movimientos."),surface)};items(filtered,key={it.id}){e->Column{Text(LocalDate.ofEpochDay(e.dateEpochDay).format(DateTimeFormatter.ofPattern("EEE, MMM d",if(es)Locale("es")else Locale.US)),color=muted,fontSize=11.sp,modifier=Modifier.padding(start=5.dp,bottom=4.dp,top=7.dp));Row(verticalAlignment=Alignment.CenterVertically){Box(Modifier.weight(1f)){EntryCard(e,accounts,ink,surface){edit(e)}};IconButton(onClick={edit(e)}){Icon(Icons.Default.Edit,null,tint=muted)};IconButton(onClick={delete(e.id)}){Icon(Icons.Default.DeleteOutline,null,tint=rose)}}}}}}}

@Composable private fun Reports(entries:List<LedgerEntry>,accounts:List<Account>,es:Boolean,ink:Color,surface:Color){
    var year by remember{mutableIntStateOf(LocalDate.now().year)}
    var currency by remember(accounts){mutableStateOf(accounts.firstOrNull()?.currency?.uppercase()?:"USD")}
    val totals=FinanceEngine.summariesByCurrency(entries,accounts,LocalDate.of(year,1,1).toEpochDay(),LocalDate.of(year+1,1,1).toEpochDay())
    val summary=totals[currency]?:FinanceEngine.Summary(0,0,0)
    val accountIds=accounts.filter{it.currency.equals(currency,true)}.map{it.id}.toSet()
    val categories=FinanceEngine.categorySpend(entries.filter{it.accountId in accountIds},LocalDate.of(year,1,1).toEpochDay(),LocalDate.of(year+1,1,1).toEpochDay()).toList().sortedByDescending{it.second}
    LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(20.dp,17.dp,20.dp,100.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){
        item{Row(verticalAlignment=Alignment.CenterVertically){Text(tr(es,"Insights","Análisis"),Modifier.weight(1f),color=ink,fontSize=27.sp,fontWeight=FontWeight.Bold);IconButton(onClick={year--}){Icon(Icons.Default.ChevronLeft,null)};Text(year.toString(),fontWeight=FontWeight.Bold);IconButton(onClick={year++}){Icon(Icons.Default.ChevronRight,null)}}}
        if(totals.size>1)item{Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(7.dp)){totals.keys.forEach{FilterChip(currency==it,{currency=it},label={Text(it)})}}}
        item{Surface(shape=RoundedCornerShape(24.dp),color=surface){Column(Modifier.padding(20.dp)){Text(tr(es,"Yearly overview","Resumen anual")+" · "+currency,color=muted);Text(tr(es,"Income","Ingresos")+"   "+cash(summary.income,currency),Modifier.padding(top=12.dp),color=mint,fontWeight=FontWeight.Bold);Text(tr(es,"Spent","Gastado")+"   "+cash(summary.expenses,currency),Modifier.padding(top=7.dp),color=rose,fontWeight=FontWeight.Bold);Text(tr(es,"Net savings","Ahorro neto")+"   "+cash(summary.net,currency),Modifier.padding(top=7.dp),color=purple,fontWeight=FontWeight.Bold)}}}
        item{Text(tr(es,"Spending by category","Gastos por categoría"),fontSize=18.sp,fontWeight=FontWeight.Bold)}
        if(categories.isEmpty())item{Empty(tr(es,"No spending yet","Sin gastos todavía"),tr(es,"Your breakdown appears after you add expenses.","El resumen aparecerá al registrar gastos."),surface)}
        items(categories){(name,value)->Surface(shape=RoundedCornerShape(17.dp),color=surface){Column(Modifier.padding(14.dp)){Row{Text(name,Modifier.weight(1f));Text(cash(value,currency),fontWeight=FontWeight.Bold)};LinearProgressIndicator(progress={value.toFloat()/summary.expenses.coerceAtLeast(1)},Modifier.fillMaxWidth().padding(top=9.dp),color=purple)}}}
    }
}}
@Composable private fun Plans(goals:List<Goal>,projects:List<Project>,entries:List<LedgerEntry>,accounts:List<Account>,es:Boolean,ink:Color,surface:Color,newGoal:()->Unit,newProject:()->Unit,contribute:(Goal)->Unit){var selected by remember{mutableIntStateOf(0)};Column(Modifier.fillMaxSize().padding(horizontal=19.dp)){Row(verticalAlignment=Alignment.CenterVertically,modifier=Modifier.padding(top=15.dp)){Text(tr(es,"Plans","Planes"),Modifier.weight(1f),color=ink,fontSize=27.sp,fontWeight=FontWeight.Bold);IconButton(onClick={if(selected==0)newGoal()else newProject()}){Icon(Icons.Default.AddCircle,null,tint=purple)}};TabRow(selectedTabIndex=selected,containerColor=Color.Transparent){listOf(tr(es,"Goals","Metas"),tr(es,"Projects","Proyectos")).forEachIndexed{i,t->Tab(selected==i,{selected=i},text={Text(t)})}};if(selected==0){if(goals.isEmpty())Empty(tr(es,"Give savings a goal","Ponle una meta a tu ahorro"),tr(es,"Create a goal to track progress.","Crea una meta y sigue tu avance."),surface);LazyColumn(Modifier.weight(1f),contentPadding=PaddingValues(top=10.dp,bottom=100.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){items(goals,key={it.id}){GoalCard(it,es,ink,surface){contribute(it)}}}}else{if(projects.isEmpty())Empty(tr(es,"Track a project","Controla un proyecto"),tr(es,"Assign transactions to a project.","Asigna movimientos a un proyecto."),surface);LazyColumn(Modifier.weight(1f),contentPadding=PaddingValues(top=10.dp,bottom=100.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){items(projects,key={it.id}){p->val spent=entries.filter{it.projectId==p.id&&it.type=="expense"&&accounts.firstOrNull{a->a.id==it.accountId}?.currency.equals(p.currency,true)}.fold(0L){total,entry->Math.addExact(total,entry.amountCents)};Surface(color=surface,shape=RoundedCornerShape(19.dp)){Column(Modifier.padding(15.dp)){Row{Text(p.name,Modifier.weight(1f),fontWeight=FontWeight.Bold);Text(cash(spent,p.currency)+" / "+cash(p.budgetCents,p.currency),fontSize=12.sp,color=muted)};LinearProgressIndicator(progress={if(p.budgetCents==0L)0f else (spent.toFloat()/p.budgetCents).coerceIn(0f,1f)},Modifier.fillMaxWidth().padding(top=8.dp),color=mint)}}}}}}}
@Composable private fun GoalCard(goal:Goal,es:Boolean,ink:Color,surface:Color,onContribute:()->Unit={}){val p=FinanceEngine.goalProgress(goal).toFloat();Surface(color=surface,shape=RoundedCornerShape(19.dp),shadowElevation=1.dp){Column(Modifier.padding(15.dp)){Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Flag,null,tint=Color(goal.color));Text(goal.name,Modifier.weight(1f).padding(start=8.dp),color=ink,fontWeight=FontWeight.SemiBold);Text("${(p*100).toInt()}%",color=purple,fontWeight=FontWeight.Bold)};LinearProgressIndicator(progress={p},Modifier.fillMaxWidth().padding(top=10.dp),color=purple);Row(Modifier.fillMaxWidth().padding(top=6.dp),verticalAlignment=Alignment.CenterVertically){Text(cash(goal.savedCents)+" / "+cash(goal.targetCents),Modifier.weight(1f),color=muted,fontSize=12.sp);TextButton(onClick=onContribute){Text(tr(es,"Add savings","Aportar ahorro"),fontSize=12.sp)}}}}}

