@Composable private fun TransactionForm(initial:LedgerEntry?,initialType:String,accounts:List<Account>,projects:List<Project>,es:Boolean,dismiss:()->Unit,save:(String?,String,String,String,String,String,String,String?,String?)->Unit){var type by remember(initial){mutableStateOf(initial?.type?:initialType)};var amount by remember(initial){mutableStateOf(initial?.let{"%.2f".format(Locale.US,it.amountCents/100.0)}?:"")};var category by remember(initial){mutableStateOf(initial?.category?:if(type=="income")"Salary" else "Food")};var note by remember(initial){mutableStateOf(initial?.note?:"")};var date by remember(initial){mutableStateOf(initial?.let{LocalDate.ofEpochDay(it.dateEpochDay).toString()}?:LocalDate.now().toString())};var account by remember(initial,accounts){mutableStateOf(initial?.accountId?:accounts.firstOrNull()?.id.orEmpty())};var target by remember(initial,accounts){mutableStateOf(initial?.targetAccountId?:accounts.firstOrNull{it.id!=account}?.id.orEmpty())};var project by remember(initial){mutableStateOf(initial?.projectId.orEmpty())};var error by remember{mutableStateOf("")};var showSmallCalc by remember{mutableStateOf(false)};AlertDialog(onDismissRequest=dismiss,title={Text(if(initial==null)tr(es,"New transaction","Nuevo movimiento")else tr(es,"Edit transaction","Editar movimiento"),fontWeight=FontWeight.Bold)},text={Column(verticalArrangement=Arrangement.spacedBy(7.dp)){Row(horizontalArrangement=Arrangement.spacedBy(4.dp)){listOf("expense","income","transfer").forEach{k->FilterChip(type==k,{type=k},label={Text(when(k){"expense"->tr(es,"Expense","Gasto");"income"->tr(es,"Income","Ingreso");else->tr(es,"Transfer","Transferir")})})}};OutlinedTextField(amount,{amount=it;error=""},label={Text(tr(es,"Amount","Monto"))},leadingIcon={Text("$",Modifier.padding(start=8.dp))},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal),singleLine=true);if(type=="expense"){TextButton(onClick={showSmallCalc=true}){Text(tr(es,"Calculate a small expense","Calcular un gasto pequeño"))};if(showSmallCalc)SmallExpenseForm(es,{showSmallCalc=false},{amount=it;showSmallCalc=false})};if(type!="transfer")OutlinedTextField(category,{category=it},label={Text(tr(es,"Category","Categoría"))},singleLine=true);OutlinedTextField(note,{note=it},label={Text(tr(es,"Note (optional)","Nota (opcional)"))},singleLine=true);OutlinedTextField(date,{date=it},label={Text(tr(es,"Date (YYYY-MM-DD)","Fecha (AAAA-MM-DD)"))},singleLine=true);if(accounts.isEmpty())Text(tr(es,"Add an account before recording a transaction.","Agrega una cuenta antes de registrar movimientos."),color=rose,fontSize=12.sp) else{Row(verticalAlignment=Alignment.CenterVertically){Text(tr(es,"From","Desde")+": ",fontSize=11.sp);ChoiceMenu(accounts,account){account=it};if(type=="transfer"){Text(tr(es,"To","A")+": ",fontSize=11.sp);ChoiceMenu(accounts.filter{it.id!=account&&it.currency.equals(accounts.firstOrNull{a->a.id==account}?.currency,true)},target){target=it}}}};if(type=="expense"&&projects.isNotEmpty())ChoiceMenu(listOf(Project("","No project"))+projects,project){project=it};if(error.isNotBlank())Text(error,color=rose,fontSize=12.sp)}},confirmButton={TextButton(onClick={try{FinanceViewModel.parseCents(amount);LocalDate.parse(date);require(account.isNotBlank());require(type!="transfer"||(target.isNotBlank()&&accounts.firstOrNull{it.id==account}?.currency.equals(accounts.firstOrNull{it.id==target}?.currency,true)));save(initial?.id,amount,type,category,note,date,account,target.ifBlank{null},project.ifBlank{null})}catch(_:Exception){error=tr(es,"Enter a positive amount and valid date.","Ingresa un monto positivo y una fecha válida.")}}){Text(tr(es,"Save","Guardar"))}},dismissButton={TextButton(onClick=dismiss){Text(tr(es,"Cancel","Cancelar"))}})}
@Composable private fun ChoiceMenu(options:List<*>,selected:String,pick:(String)->Unit){var open by remember{mutableStateOf(false)};val label=when(val v=options.firstOrNull{when(it){is Account->it.id==selected;is Project->it.id==selected;else->false}}){is Account->v.name;is Project->v.name;else->"—"};Box{TextButton(onClick={open=true}){Text(label,fontSize=11.sp)};DropdownMenu(open,{open=false}){options.forEach{v->val id=when(v){is Account->v.id;is Project->v.id;else->""};val name=when(v){is Account->v.name;is Project->v.name;else->""};DropdownMenuItem(text={Text(name)},onClick={pick(id);open=false})}}}}
@Composable private fun EntityForm(kind:String,es:Boolean,dismiss:()->Unit,save:(String,String,String,String)->Unit){val account=kind=="account";val title=when(kind){"account"->tr(es,"New account","Nueva cuenta");"goal"->tr(es,"New savings goal","Nueva meta de ahorro");else->tr(es,"New project","Nuevo proyecto")};var name by remember{mutableStateOf("")};var amount by remember{mutableStateOf("")};var currency by remember{mutableStateOf("USD")};var type by remember{mutableStateOf("cash")};AlertDialog(onDismissRequest=dismiss,title={Text(title)},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(name,{name=it},label={Text(if(account)tr(es,"Account name","Nombre de cuenta")else tr(es,"Name","Nombre"))},singleLine=true);OutlinedTextField(amount,{amount=it},label={Text(if(account)tr(es,"Opening balance","Saldo inicial")else tr(es,"Target / budget","Meta / presupuesto"))},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal),singleLine=true);if(account||kind=="project")OutlinedTextField(currency,{currency=it.uppercase()},label={Text("Currency (USD, EUR…)")},singleLine=true);if(account)OutlinedTextField(type,{type=it},label={Text(tr(es,"Type (cash, bank, card)","Tipo (efectivo, banco, tarjeta)"))},singleLine=true)}},confirmButton={TextButton(onClick={if(name.isNotBlank()&&(account||runCatching{FinanceViewModel.parseCents(amount)}.isSuccess))save(name,amount,type,currency)}){Text(tr(es,"Save","Guardar"))}},dismissButton={TextButton(onClick=dismiss){Text(tr(es,"Cancel","Cancelar"))}})}

@Composable private fun ContributionForm(goal:Goal,es:Boolean,dismiss:()->Unit,save:(String)->Unit){var amount by remember{mutableStateOf("")};var error by remember{mutableStateOf("")};AlertDialog(onDismissRequest=dismiss,title={Text(tr(es,"Add to ","Aportar a ")+goal.name)},text={Column(verticalArrangement=Arrangement.spacedBy(7.dp)){Text(tr(es,"Current progress: ","Progreso actual: ")+cash(goal.savedCents)+" / "+cash(goal.targetCents),color=muted);OutlinedTextField(amount,{amount=it;error=""},label={Text(tr(es,"Contribution","Aporte"))},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal),singleLine=true);if(error.isNotBlank())Text(error,color=rose,fontSize=12.sp)}},confirmButton={TextButton(onClick={runCatching{FinanceViewModel.parseCents(amount)}.onSuccess{save(amount)}.onFailure{error=tr(es,"Enter a positive amount.","Ingresa un monto positivo.")}}){Text(tr(es,"Add","Aportar"))}},dismissButton={TextButton(onClick=dismiss){Text(tr(es,"Cancel","Cancelar"))}})}

